            let tmp5 = (Custard_FStar_Pervasives_Native.fStar_Pervasives_Native_fst tmp4) in
            (FStarC_List.length tmp5)) else (let tmp4 = (FStarC_Syntax_Util.abs_formals def) in
            (match tmp4 with
