let rec repeat_unit (n : Prims.int) : (unit) list =
  (if (Prims.op_Less_Equals n (Prims.parse_int "0")) then [] else (let tmp = (repeat_unit (Prims.op_Minus n (Prims.parse_int "1"))) in
  (() :: tmp)))

let rec apply_eff (st : state) (ty : FStarC_Custard_Syntax.cty) (n : Prims.int) : FStarC_Custard_Syntax.eff =
